const http = require('http');
const WebSocket = require('ws');
const { Pool } = require('pg');

const pool = new Pool();
const server = http.createServer();
const wss = new WebSocket.Server({ server });

wss.on('connection', (ws, req) => {
  const tokenUser = req.headers['x-authenticated-user'];
  if (!tokenUser) {
    ws.close(4003, 'Missing auth');
    return;
  }
  ws.userId = tokenUser;

  ws.on('message', async (raw) => {
    const { canvasId, shapeDelta } = JSON.parse(raw);

    // Check membership on target canvas
    const memberCheck = await pool.query(
      'SELECT 1 FROM canvas_collaborators WHERE canvas_id = $1 AND user_id = $2',
      [canvasId, ws.userId]
    );

    if (memberCheck.rowCount === 0) {
      ws.send(JSON.stringify({ error: 'Access denied: not a collaborator on this canvas' }));
      return;
    }

    await pool.query(
      'INSERT INTO whiteboard_actions (canvas_id, user_id, delta_payload, created_at) VALUES ($1, $2, $3, NOW())',
      [canvasId, ws.userId, JSON.stringify(shapeDelta)]
    );

    ws.send(JSON.stringify({ status: 'ACK', canvasId }));
  });
});

server.listen(8003);
